const list = [];
const push = function(title, url, size) {
    list.push({
        title: title,
        url: url,
        style: {layout_flexBasisPercent: size}
    });
};

const tpl = "/index.php/api/data/comic?type%5Btags%5D=$id&type%5Border%5D=hits&type%5Blist%5D=0&type%5Bpay%5D=0&type%5Bfinish%5D=0";
const catUrl = java.toURL(source.key).origin + "/category/";
const doc = org.jsoup.Jsoup.parse(java.ajax(catUrl));
const cates = doc.select("#cates a");
const tags = [];
cates.forEach(cat => {
  let title = cat.text().trim()
  let len = title.length();
  if(len === 0 || len > 4) return;
  let href = String(cat.attr("href") || "");
  if(!href) return;
  let id = href?.match(/\d+$/)?.[0] || "";
  let url = "";
  if(title == "全部"){
    url = tpl.replace(/\?.*/, "") + "?page={{page}}";
    url += "," + JSON.stringify({headers:{Referer: catUrl}})
  }else{
    url = tpl.replace("$id", id) + "&page={{page}}," + JSON.stringify({headers:{Referer: catUrl+"tags/"+id}})
  }
  push(title, url, 0.2)
})

JSON.stringify(list)

